/bin/bash -lc "node --input-type=module <<'EOF'
import { createServer } from './src/server.js';
const server = createServer({ projectAdmins: { demo: ['admin'] }, baseUrl: 'http://localhost' });
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const url = "'`http://127.0.0.1:${server.address().port}`;
const form = await fetch(url);
const headers = { Authorization: '"'Bearer admin', 'Content-Type': 'application/json', 'Idempotency-Key': 'live-1' };
const body = JSON.stringify({ email: 'user@example.com', role: 'editor' });
const first = await fetch("'`${url}/api/projects/demo/invites`, { method: '"'POST', headers, body });
const second = await fetch("'`${url}/api/projects/demo/invites`, { method: '"'POST', headers, body });
const a = await first.json(); const b = await second.json();
console.log(JSON.stringify({ form: form.status, first: first.status, retry: second.status, sameInvite: a.inviteUrl === b.inviteUrl, role: a.role }));
server.close();
EOF"

